proc sql; create table pcDATA1 as select distinct
	a.*, b.gvkey, b.permco
	from mydir.PressCoverage a left join sp1500.sp1500 b
	on a.company_name eq b.coname
	where year(a.date) ge 2001;
quit;

*Reformat variables;
data pcDATA2; set pcDATA1;
