format date YYMMDDN8.;
drop gvkey;
rename gvkeyNUM=gvkey;
run;

*Address articles that are promoted from online to print;
data pc_online; set pcDATA2; where medium eq 'Online'; run;
data pc_print; set pcDATA2; where medium eq 'Print'; run;

proc sql; create table pc_print1 as select distinct
	a.*, b.date as dum
	from pc_print a left join pc_online b
