proc sql; 
	*Volume and spread;
	create table aspr0 as select
	a.*, b.date, b.VOL, log(1+((b.vol/1000)/b.shrout)) as volume, b.BID, b.ASK, (b.ask-b.bid)/((b.ask+b.bid)/2) as spread
	from aspr as a left join crsp.dsf as b
	on a.permno eq b.permno
	and intnx('day',a.prdate,-100) <= b.date <= intnx('day',a.prdate,6)
	where b.ask-b.bid ge 0;

	*MIA;
	create table aspr1 as select
	a.*, b.mia
	from aspr0 as a left join miadata2006to2015 as b
	on a.permno eq b.permno and a.date eq b.date;
quit;

*rsubmit;
*Identify days in (t-60,t+2);
data aspr2; set aspr1; if prdate >= date then keep=1; else keep=0; run;
proc sort data=aspr2; by permno prdate date; run;
data aspr3; set aspr2; lagkeep=lag(keep); lagkeep2=lag2(keep); run;
data aspr4; set aspr3; where lagkeep=1 or lagkeep2=1 or keep=1; drop keep lagkeep lagkeep2; run;

*rsubmit;
*Only keep days in (t-60,t+2);
proc sort data=aspr4; by permno prdate descending date; run;
data aspr5; set aspr4; firmdate = permno + prdate/1000000; run;
data aspr6; set aspr5; count + 1; by firmdate; if first.firmdate then count = -2; run;
data aspr7; set aspr6; where (count le 60);  run;

*Split into EA and pre-EA;
*rsubmit;
data duringEA; set aspr7; where count le 0; run;
data beforeEA; set aspr7; where count gt 0; run;

*Calculate abnormal returns, noise during EA, and turnover during EA;
proc sql; create table duringEA1 as select distinct
	permno, prdate, mean(volume) as during_volume, mean(spread) as during_spread, mean(mia) as during_mia, count(spread) as nEA
	from duringEA 
	group by permno, prdate
	order by permno, prdate;
	quit;
data duringEA2; set duringEA1; if nEA lt 3 then during_volume=.; if nEA lt 3 then during_spread=.; run;

proc sql; create table beforeEA1 as select distinct
	permno, prdate, mean(volume) as pre_volume, mean(spread) as pre_spread, mean(mia) as pre_mia, count(spread) as nPRE
	from beforeEA 
	group by permno, prdate
	order by permno, prdate;
	quit;
data beforeEA2; set beforeEA1; if nPRE lt 60 then pre_volume=.; if nPRE lt 60 then pre_spread=.; run;

*Merge to other data;
*rsubmit;
proc sql;
	create table gc12_pre1 as select
	a.*, b.during_volume, b.during_spread, b.during_mia
	from gc12 as a left join duringEA2 as b
	on a.permno eq b.permno and a.prdate eq b.prdate;

	create table gc12_pre2 as select
	a.*, b.pre_volume, b.pre_spread, b.pre_mia
	from gc12_pre1 as a left join beforeEA2 as b
	on a.permno eq b.permno and a.prdate eq b.prdate;
quit;

*Calculate abnormal variables;
*rsubmit;
data gc13; set gc12_pre2;
ABvolume=during_volume-pre_volume;
ABspread=during_spread-pre_spread;
ABmia=during_mia-pre_mia;
rename during_mia=mia;
run;




