%* Assign values to the dummy variables for the j-th input variable;
%******************************************************************;
data &out  ( rename = ( %do k=1 %to &num ;
						d&k = &pre.&k
						%end ; ) ) ;
	set &out ;

proc upload data=gc16; run;
proc sql; create table gc17 as select
	a.*, b.SPMIM, abs(a.prdate-b.datadate) as closestSPMIM
	from gc16 as a left join comp.secm as b
	on a.gvkey eq b.gvkey and intnx('month',a.prdate,-2) <= b.datadate <= intnx('month',a.prdate,2)
	where SPMIM ne '';
	quit;
proc sort data=gc17; by myfname nitem closestSPMIM; run;
proc sort data=gc17 nodupkey; by myfname nitem; run;


* Get prior month stock return volatility for matching procedure;
*rsubmit;
proc sql; create table matchRV0 as select
	a.permno, a.myfname, a.nitem as nitem8k, a.prdate, b.date, b.ret
	from gc17 as a left join crsp.dsf as b
	on a.permno eq b.permno and intnx('day',a.prdate,-31) <= b.date <= intnx('day',a.prdate,-2)
	order by a.permno, a.myfname, a.nitem, b.date;
	quit;

