quit;


*Create pseudo-firms based on size and btm;
proc rank data=gc21 out=pseudo1 groups=10; var SIZE; ranks rSIZE; run;
proc rank data=pseudo1 out=pseudo2 groups=10; var BTM; ranks rBTM; run;
data mydir.gc21_20200212; set pseudo2; pseudo=cat(rSIZE,rBTM); drop rSIZE rBTM; run;


